// To do 생성/편집 모달
import { useState, useEffect, useRef } from 'react';
import type { Project, ProjectTask, ProjectTodo, TodoStatus } from '../../types/work';
import { useDraggable } from '../../hooks/useDraggable';
import './TodoModal.css';

// 상태 순환
const STATUS_CYCLE: TodoStatus[] = ['active', 'done', 'delayed', 'cancelled'];
const STATUS_ICONS: Record<TodoStatus, string> = {
  active: '○',
  done: '✓',
  delayed: '⏳',
  cancelled: '✕',
};
const STATUS_LABELS: Record<TodoStatus, string> = {
  active: '진행중',
  done: '완료됨',
  delayed: '연기됨',
  cancelled: '취소됨',
};

interface TodoModalProps {
  todo: ProjectTodo | null; // null이면 새 투두 생성
  isOpen: boolean;
  tasks: ProjectTask[]; // 태스크 목록
  projects: Project[]; // 프로젝트 목록 (색상용)
  defaultTaskId?: string | null;
  onClose: () => void;
  onSave: (todo: Partial<ProjectTodo>) => void;
  onDelete?: (todoId: string) => void;
}

export default function TodoModal({
  todo,
  isOpen,
  tasks,
  projects,
  defaultTaskId,
  onClose,
  onSave,
  onDelete,
}: TodoModalProps) {
  const [content, setContent] = useState('');
  const [note, setNote] = useState('');
  const [url, setUrl] = useState('');
  const [taskId, setTaskId] = useState<string | null>(null);
  const [startDate, setStartDate] = useState('');
  const [startTime, setStartTime] = useState('');
  const [endDate, setEndDate] = useState('');
  const [endTime, setEndTime] = useState('');
  const [dueDate, setDueDate] = useState('');
  const [dueTime, setDueTime] = useState('');
  const [isAllDay, setIsAllDay] = useState(true);
  const [showInCalendar, setShowInCalendar] = useState(false);
  const [status, setStatus] = useState<TodoStatus>('active');
  const [isSaving, setIsSaving] = useState(false);
  const [dateError, setDateError] = useState('');
  
  const contentRef = useRef<HTMLInputElement>(null);
  const { position, isDragging, handleMouseDown, resetPosition } = useDraggable('todo');

  const isNew = !todo;

  // 날짜/시간 파싱
  const parseDateTime = (isoDate: string | null) => {
    if (!isoDate) return { date: '', time: '' };
    const [datePart, timePart] = isoDate.split('T');
    return { 
      date: datePart || '', 
      time: timePart ? timePart.slice(0, 5) : '' 
    };
  };

  // 날짜/시간 결합
  const combineDateTime = (date: string, time: string, isAllDay: boolean): string | null => {
    if (!date) return null;
    if (isAllDay || !time) {
      return `${date}T00:00:00`;
    }
    return `${date}T${time}:00`;
  };

  // 날짜 유효성 검사
  const validateDates = (): boolean => {
    if (startDate && endDate) {
      const startDateTime = new Date(`${startDate}T${startTime || '00:00'}`);
      const endDateTime = new Date(`${endDate}T${endTime || '23:59'}`);
      if (endDateTime < startDateTime) {
        setDateError('종료일은 시작일보다 이후여야 합니다');
        return false;
      }
    }
    setDateError('');
    return true;
  };

  useEffect(() => {
    if (isOpen) {
      if (todo) {
        setContent(todo.content);
        setNote(todo.note || '');
        setUrl(todo.url || '');
        setTaskId(todo.taskId);
        
        const start = parseDateTime(todo.start_at);
        setStartDate(start.date);
        setStartTime(start.time);
        
        const end = parseDateTime(todo.end_at);
        setEndDate(end.date);
        setEndTime(end.time);
        
        const due = parseDateTime(todo.due_at);
        setDueDate(due.date);
        setDueTime(due.time);
        
        setIsAllDay(todo.is_all_day);
        setShowInCalendar(todo.show_in_calendar ?? false);
        // 상태 복원 (is_done과 호환)
        if (todo.status) {
          setStatus(todo.status);
        } else {
          setStatus(todo.is_done ? 'done' : 'active');
        }
      } else {
        // 새 투두
        setContent('');
        setNote('');
        setUrl('');
        setTaskId(defaultTaskId || null);
        setStartDate('');
        setStartTime('');
        setEndDate('');
        setEndTime('');
        setDueDate('');
        setDueTime('');
        setIsAllDay(true);
        setShowInCalendar(false);
        setStatus('active');
      }
      setDateError('');
      resetPosition();
      setTimeout(() => contentRef.current?.focus(), 100);
    }
  }, [isOpen, todo, defaultTaskId, resetPosition]);

  const handleSave = async () => {
    if (!content.trim() || isSaving) return;
    if (!validateDates()) return;
    
    setIsSaving(true);
    try {
      await onSave({
        ...todo,
        content: content.trim(),
        note: note.trim(),
        url: url.trim() || undefined,
        taskId,
        start_at: combineDateTime(startDate, startTime, isAllDay),
        end_at: combineDateTime(endDate, endTime, isAllDay),
        due_at: combineDateTime(dueDate, dueTime, isAllDay),
        is_all_day: isAllDay,
        show_in_calendar: showInCalendar,
        status,
        is_done: status === 'done',
        completed_at: status === 'done' ? Date.now() : null,
      });
      onClose();
    } catch (error) {
      console.error('Failed to save todo:', error);
      alert('저장에 실패했습니다.');
    } finally {
      setIsSaving(false);
    }
  };
  
  // 상태 순환
  const handleStatusCycle = () => {
    const currentIndex = STATUS_CYCLE.indexOf(status);
    const nextIndex = (currentIndex + 1) % STATUS_CYCLE.length;
    setStatus(STATUS_CYCLE[nextIndex]);
  };

  const handleDelete = () => {
    if (!todo || !onDelete) return;
    if (confirm('정말로 이 To do를 삭제하시겠습니까?')) {
      onDelete(todo.id);
      onClose();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape') {
      onClose();
    }
  };

  // 태스크의 프로젝트 색상 가져오기
  const getTaskColor = (tId: string | null): string => {
    if (!tId) return '#6b7280';
    const task = tasks.find(t => t.id === tId);
    if (!task?.projectId) return '#6b7280';
    const project = projects.find(p => p.id === task.projectId);
    return project?.color || '#6b7280';
  };

  if (!isOpen) return null;

  // 드래그된 위치가 있으면 적용
  const modalStyle = position ? {
    position: 'fixed' as const,
    left: position.x,
    top: position.y,
    margin: 0,
  } : undefined;

  return (
    <div className="todo-modal-overlay" onClick={onClose} onKeyDown={handleKeyDown}>
      <div 
        className={`todo-modal ${isDragging ? 'dragging' : ''}`} 
        onClick={(e) => e.stopPropagation()}
        style={modalStyle}
      >
        {/* 헤더 - 드래그 핸들 */}
        <div 
          className="modal-header draggable" 
          onMouseDown={handleMouseDown}
          style={{ borderLeftColor: getTaskColor(taskId) }}
        >
          <h2>{isNew ? 'New To do' : 'Edit To do'}</h2>
          <button className="close-btn" onClick={onClose}>×</button>
        </div>

        {/* 본문 */}
        <div className="modal-body">
          {/* 상태 선택 (클릭으로 순환) */}
          <div className={`status-badge status-${status}`}>
            <button 
              className="status-toggle" 
              onClick={handleStatusCycle}
              title="클릭하여 상태 변경"
            >
              {STATUS_ICONS[status]} {STATUS_LABELS[status]}
            </button>
          </div>

          {/* 제목 */}
          <div className="form-group">
            <label>제목 *</label>
            <input
              ref={contentRef}
              type="text"
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="To do 제목"
              onKeyDown={(e) => e.key === 'Enter' && handleSave()}
            />
          </div>

          {/* 소속 태스크 */}
          <div className="form-group">
            <label>소속 Task</label>
            <select
              value={taskId || ''}
              onChange={(e) => setTaskId(e.target.value || null)}
            >
              <option value="">미분류</option>
              {tasks.filter(t => t.status === 'ACTIVE').map((t) => (
                <option key={t.id} value={t.id}>
                  {t.title}
                </option>
              ))}
            </select>
          </div>

          {/* 메모 */}
          <div className="form-group">
            <label>메모</label>
            <textarea
              value={note}
              onChange={(e) => setNote(e.target.value)}
              placeholder="메모 추가..."
              rows={2}
            />
          </div>

          {/* URL */}
          <div className="form-group">
            <label>URL</label>
            <div className="url-input-wrapper">
              <input
                type="url"
                value={url}
                onChange={(e) => setUrl(e.target.value)}
                placeholder="https://..."
              />
              {url && (
                <a 
                  href={url.startsWith('http') ? url : `https://${url}`} 
                  target="_blank" 
                  rel="noopener noreferrer"
                  className="url-open-btn"
                  onClick={(e) => e.stopPropagation()}
                >
                  🔗
                </a>
              )}
            </div>
          </div>

          {/* 종일 여부 */}
          <div className="form-group checkbox-group">
            <label className="checkbox-label">
              <input
                type="checkbox"
                checked={isAllDay}
                onChange={(e) => setIsAllDay(e.target.checked)}
              />
              종일
            </label>
          </div>

          {/* 날짜/시간 섹션 */}
          <div className="form-group">
            <label>기간</label>
            <div className="datetime-inputs">
              <div className="datetime-field">
                <span className="datetime-label">시작</span>
                <input
                  type="date"
                  value={startDate}
                  onChange={(e) => setStartDate(e.target.value)}
                />
                {!isAllDay && (
                  <input
                    type="time"
                    value={startTime}
                    onChange={(e) => setStartTime(e.target.value)}
                  />
                )}
              </div>
              <div className="datetime-spacer" />
              <div className="datetime-field">
                <span className="datetime-label">종료</span>
                <input
                  type="date"
                  value={endDate}
                  onChange={(e) => setEndDate(e.target.value)}
                />
                {!isAllDay && (
                  <input
                    type="time"
                    value={endTime}
                    onChange={(e) => setEndTime(e.target.value)}
                  />
                )}
              </div>
            </div>
            {dateError && <span className="error-text">{dateError}</span>}
          </div>

          <div className="form-group">
            <label>마감일</label>
            <div className="datetime-single">
              <input
                type="date"
                value={dueDate}
                onChange={(e) => setDueDate(e.target.value)}
              />
              {!isAllDay && (
                <input
                  type="time"
                  value={dueTime}
                  onChange={(e) => setDueTime(e.target.value)}
                />
              )}
            </div>
          </div>

          {/* 달력 표시 여부 */}
          <div className="form-group checkbox-group">
            <label className="checkbox-label">
              <input
                type="checkbox"
                checked={showInCalendar}
                onChange={(e) => setShowInCalendar(e.target.checked)}
              />
              당일 달력에 표시
            </label>
          </div>
        </div>

        {/* 푸터 */}
        <div className="modal-footer">
          {!isNew && onDelete && (
            <button className="delete-btn" onClick={handleDelete}>
              삭제
            </button>
          )}
          <div className="footer-right">
            <button className="cancel-btn" onClick={onClose}>
              취소
            </button>
            <button 
              className="save-btn" 
              onClick={handleSave}
              disabled={!content.trim() || isSaving}
            >
              {isSaving ? '저장 중...' : (isNew ? '생성' : '저장')}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
