// Projects List 모드 컴포넌트
import React, { useState, useEffect } from 'react';
import type { Project } from '../../types/work';
import './ProjectList.css';

// 날짜 포맷 (월/일만 표시)
function formatDate(dateStr: string): string {
  if (!dateStr) return '';
  const date = new Date(dateStr);
  return `${date.getMonth() + 1}/${date.getDate()}`;
}

interface ProjectListProps {
  projects: Project[];
  archivedProjects: Project[];
  showArchived: boolean;
  onAddClick: () => void;
  onSelectProject: (project: Project) => void;
  onReorderProjects: (projectIds: string[]) => Promise<void>;
  onDeleteProject?: (projectId: string) => Promise<void>;
  onArchiveProject?: (projectId: string) => Promise<void>;
  onUnarchiveProject?: (project: Project) => Promise<void>;
  selectedProjectId?: string | null;
  // 다중 선택
  selectedIds?: Set<string>;
  onMultiSelect?: (id: string, ctrlKey: boolean) => void;
  onContextMenu?: (e: React.MouseEvent, id: string) => void;
}

export default function ProjectList({
  projects,
  archivedProjects,
  showArchived,
  onAddClick,
  onSelectProject,
  onReorderProjects,
  onDeleteProject,
  onArchiveProject,
  onUnarchiveProject,
  selectedProjectId,
  selectedIds,
  onMultiSelect,
  onContextMenu,
}: ProjectListProps) {
  const [draggedId, setDraggedId] = useState<string | null>(null);
  const [dragOverId, setDragOverId] = useState<string | null>(null);
  const [isMobile, setIsMobile] = useState(false);
  const [touchStart, setTouchStart] = useState<{ x: number; y: number } | null>(null);

  useEffect(() => {
    const checkMobile = () => setIsMobile(window.innerWidth <= 768);
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  // 터치가 탭인지 확인 (이동 거리 10px 이내)
  const isTap = (endX: number, endY: number) => {
    if (!touchStart) return false;
    const dx = Math.abs(endX - touchStart.x);
    const dy = Math.abs(endY - touchStart.y);
    return dx < 10 && dy < 10;
  };

  // 완료 토글
  const handleToggleComplete = async (e: React.MouseEvent, project: Project) => {
    e.stopPropagation();
    try {
      if (project.status === 'ARCHIVED') {
        if (onUnarchiveProject) {
          await onUnarchiveProject(project);
        }
      } else {
        if (onArchiveProject) {
          await onArchiveProject(project.id);
        }
      }
    } catch (error) {
      console.error('Failed to toggle project completion:', error);
    }
  };

  // 삭제 핸들러
  const handleDelete = async (e: React.MouseEvent, projectId: string) => {
    e.stopPropagation();
    if (!onDeleteProject) return;
    if (confirm('정말로 이 프로젝트를 삭제하시겠습니까?\n(하위 태스크와 To do도 함께 삭제됩니다)')) {
      try {
        await onDeleteProject(projectId);
      } catch (error) {
        console.error('Failed to delete project:', error);
      }
    }
  };

  // 드래그 시작
  const handleDragStart = (e: React.DragEvent, projectId: string) => {
    setDraggedId(projectId);
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', projectId);
    
    // 드래그 이미지 스타일링
    const target = e.target as HTMLElement;
    target.style.opacity = '0.5';
  };

  // 드래그 종료
  const handleDragEnd = (e: React.DragEvent) => {
    const target = e.target as HTMLElement;
    target.style.opacity = '1';
    setDraggedId(null);
    setDragOverId(null);
  };

  // 드래그 오버
  const handleDragOver = (e: React.DragEvent, projectId: string) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    if (projectId !== draggedId) {
      setDragOverId(projectId);
    }
  };

  // 드롭
  const handleDrop = async (e: React.DragEvent, targetId: string) => {
    e.preventDefault();
    
    if (!draggedId || draggedId === targetId) {
      setDraggedId(null);
      setDragOverId(null);
      return;
    }

    // 새 순서 계산
    const currentOrder = projects.map(p => p.id);
    const draggedIndex = currentOrder.indexOf(draggedId);
    const targetIndex = currentOrder.indexOf(targetId);

    if (draggedIndex === -1 || targetIndex === -1) return;

    // 배열에서 드래그된 항목 제거 후 타겟 위치에 삽입
    const newOrder = [...currentOrder];
    newOrder.splice(draggedIndex, 1);
    newOrder.splice(targetIndex, 0, draggedId);

    try {
      await onReorderProjects(newOrder);
    } catch (error) {
      console.error('Failed to reorder projects:', error);
    }

    setDraggedId(null);
    setDragOverId(null);
  };

  return (
    <div className="project-list">
      {/* 새 프로젝트 추가 버튼 */}
      <button className="add-project-btn-large" onClick={onAddClick}>
        + New Project
      </button>

      {/* 활성 프로젝트 목록 */}
      <div className="projects-section">
        {projects.length === 0 ? (
          <div className="empty-projects">
            <span className="empty-icon">📁</span>
            <p>프로젝트가 없습니다</p>
            <p className="empty-hint">위에서 새 프로젝트를 만들어보세요</p>
          </div>
        ) : (
          <ul className="projects-items">
            {projects.map((project) => (
              <li
                key={project.id}
                className={`project-item ${selectedProjectId === project.id ? 'selected' : ''} ${dragOverId === project.id ? 'drag-over' : ''} ${selectedIds?.has(project.id) ? 'multi-selected' : ''}`}
                draggable={!isMobile}
                onDragStart={(e) => !isMobile && handleDragStart(e, project.id)}
                onDragEnd={!isMobile ? handleDragEnd : undefined}
                onDragOver={(e) => handleDragOver(e, project.id)}
                onDrop={(e) => handleDrop(e, project.id)}
                onClick={(e) => {
                  if (e.ctrlKey || e.metaKey) {
                    onMultiSelect?.(project.id, true);
                  } else if (selectedIds && selectedIds.size > 0) {
                    onMultiSelect?.(project.id, false);
                  } else {
                    onSelectProject(project);
                  }
                }}
                onContextMenu={(e) => onContextMenu?.(e, project.id)}
                onTouchStart={(e) => {
                  setTouchStart({ x: e.touches[0].clientX, y: e.touches[0].clientY });
                }}
                onTouchEnd={(e) => {
                  if ((e.target as HTMLElement).closest('button')) return;
                  const touch = e.changedTouches[0];
                  if (isTap(touch.clientX, touch.clientY)) {
                    e.preventDefault();
                    onSelectProject(project);
                  }
                  setTouchStart(null);
                }}
              >
                {onArchiveProject && (
                  <button
                    className="complete-btn"
                    onClick={(e) => handleToggleComplete(e, project)}
                    title="완료 처리"
                  >
                    ○
                  </button>
                )}
                <span
                  className="project-color"
                  style={{ backgroundColor: project.color }}
                />
                <div className="project-content">
                  <span className="project-title">{project.title}</span>
                  {/* URL 아이콘 */}
                  {project.url && (
                    <a
                      href={project.url.startsWith('http') ? project.url : `https://${project.url}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="project-url-icon"
                      onClick={(e) => e.stopPropagation()}
                      title={project.url}
                    >
                      🔗
                    </a>
                  )}
                </div>
                {/* 마감일 또는 종료일 표시 (오른쪽) */}
                {(project.due_at || project.end_at) && (
                  <span className="project-date-badge">
                    {project.due_at ? `마감: ${formatDate(project.due_at)}` : `종료: ${formatDate(project.end_at || '')}`}
                  </span>
                )}
                <span className="drag-handle">⋮⋮</span>
                {onDeleteProject && (
                  <button
                    className="delete-btn"
                    onClick={(e) => handleDelete(e, project.id)}
                    title="삭제"
                  >
                    ×
                  </button>
                )}
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* 완료된 프로젝트 */}
      {showArchived && archivedProjects.length > 0 && (
        <div className="archived-section">
          <div className="section-header">
            <span className="section-title">✓ 완료됨</span>
            <span className="section-count">{archivedProjects.length}</span>
          </div>
          <ul className="projects-items archived">
            {archivedProjects.map((project) => (
              <li
                key={project.id}
                className={`project-item archived ${selectedProjectId === project.id ? 'selected' : ''} ${selectedIds?.has(project.id) ? 'multi-selected' : ''}`}
                onClick={(e) => {
                  if (e.ctrlKey || e.metaKey) {
                    onMultiSelect?.(project.id, true);
                  } else if (selectedIds && selectedIds.size > 0) {
                    onMultiSelect?.(project.id, false);
                  } else {
                    onSelectProject(project);
                  }
                }}
                onContextMenu={(e) => onContextMenu?.(e, project.id)}
                onTouchStart={(e) => {
                  setTouchStart({ x: e.touches[0].clientX, y: e.touches[0].clientY });
                }}
                onTouchEnd={(e) => {
                  if ((e.target as HTMLElement).closest('button')) return;
                  const touch = e.changedTouches[0];
                  if (isTap(touch.clientX, touch.clientY)) {
                    e.preventDefault();
                    onSelectProject(project);
                  }
                  setTouchStart(null);
                }}
              >
                {onUnarchiveProject && (
                  <button
                    className="complete-btn done"
                    onClick={(e) => handleToggleComplete(e, project)}
                    title="완료 취소"
                  >
                    ✓
                  </button>
                )}
                <span
                  className="project-color"
                  style={{ backgroundColor: project.color }}
                />
                <div className="project-content">
                  <span className="project-title">{project.title}</span>
                  {/* URL 아이콘 */}
                  {project.url && (
                    <a
                      href={project.url.startsWith('http') ? project.url : `https://${project.url}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="project-url-icon"
                      onClick={(e) => e.stopPropagation()}
                      title={project.url}
                    >
                      🔗
                    </a>
                  )}
                </div>
                {/* 마감일 또는 종료일 표시 (오른쪽) */}
                {(project.due_at || project.end_at) && (
                  <span className="project-date-badge">
                    {project.due_at ? `마감: ${formatDate(project.due_at)}` : `종료: ${formatDate(project.end_at || '')}`}
                  </span>
                )}
                <span className="drag-handle">⋮⋮</span>
                {onDeleteProject && (
                  <button
                    className="delete-btn"
                    onClick={(e) => handleDelete(e, project.id)}
                    title="삭제"
                  >
                    ×
                  </button>
                )}
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}
